// entities/vectorindex/common/config.go lines 95-110 (OptionalStringFromMap):
func OptionalStringFromMap(in map[string]interface{}, name string,
	setFn func(v string),
) error {
	value, ok := in[name]
	if !ok {
		return nil  // <-- KEY MISSING: DOES NOTHING, DEFAULT STAYS
	}

	asString, ok := value.(string)
	if !ok {
		return nil  // <-- VALUE IS NOT STRING (e.g., null): DOES NOTHING, DEFAULT STAYS
	}

	setFn(asString)
	return nil
}
